dslRule:
private org.eclipse.swt.graphics.Color $name; :: elementKindMatches($name, "FIELD") && !isFinal($name)
=> private final org.eclipse.swt.graphics.Color $name;
;;

beforeExample:
package test;

import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;

public class MyClass {
    private Color fForegroundColor;
    private Color fBackgroundColor;
    private int otherField;

    public MyClass(Shell parent) {
        fForegroundColor = parent.getDisplay().getSystemColor(SWT.COLOR_INFO_FOREGROUND);
        fBackgroundColor = parent.getDisplay().getSystemColor(SWT.COLOR_INFO_BACKGROUND);
        otherField = 1;
    }
}

afterExample:
package test;

import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;

public class MyClass {
    private final Color fForegroundColor;
    private final Color fBackgroundColor;
    private int otherField;

    public MyClass(Shell parent) {
        fForegroundColor = parent.getDisplay().getSystemColor(SWT.COLOR_INFO_FOREGROUND);
        fBackgroundColor = parent.getDisplay().getSystemColor(SWT.COLOR_INFO_BACKGROUND);
        otherField = 1;
    }
}

negativeExample:
package test;

import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;

public class MyClass {
    private final Color fForegroundColor; // Already final, should not match
    protected Color protectedColor; // Not private, should not match
    private String someString; // Not Color type, should not match

    public MyClass(Shell parent) {
        fForegroundColor = parent.getDisplay().getSystemColor(SWT.COLOR_INFO_FOREGROUND);
        protectedColor = parent.getDisplay().getSystemColor(SWT.COLOR_BLUE);
        someString = "hello";
    }

    public void someMethod() {
        Color localColor; // Local variable, not a field, should not match
        localColor = null;
    }
}
